WITH enriched AS (SELECT *, LAST_VALUE(country) IGNORE NULLS OVER w_part AS last_known_country, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS seq_no, FIRST_VALUE(browser, TRUE) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions WINDOW w_part AS (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.customer_id, s.device, s.country, s.last_known_country, s.seq_no, s.first_known_browser, CASE WHEN device RLIKE '^(tablet|desktop)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS device_zone, (SELECT AVG(t2.discount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS avg_order_discount FROM enriched s ORDER BY id DESC NULLS FIRST, seq_no;
